#!/usr/bin/env python3
"""Create an offline interactive report from retained experiment artifacts."""
import argparse
import json
from pathlib import Path


def collect(root):
    subjects=[]
    for matrix_path in sorted(root.rglob('matrix.json')):
        path=matrix_path.parent/'analysis.json'
        if 'dependencies' in str(path) or 'history' in path.parts:
            continue
        matrix=json.loads(matrix_path.read_text())
        analysis=json.loads(path.read_text()) if path.exists() else {'complete':False,'baselineComplete':False,'tests':[],'requirements':[],
            'redundancyGroups':[], 'summary':{'tests':len(matrix.get('tests',[])),'acceptedMutants':0,'killedMutants':0,
            'subsumingRequirements':0,'greedyCoreTests':0,'unexplainedSurvivors':0,'excludedMutants':len(matrix.get('mutants',[]))}}
        subjects.append({'id':path.parent.name,'analysis':analysis,'matrix':matrix,
                         'evidence':str(path.parent.resolve())})
    history=root/'history'
    attempts=json.loads((history/'attempts.json').read_text()) if (history/'attempts.json').exists() else []
    aggregate=json.loads((history/'aggregate.json').read_text()) if (history/'aggregate.json').exists() else {'faults':0,'comparisons':[]}
    for fault in attempts:
        directory=history/fault['id']
        fault['evidence']=str(directory.resolve())
        if (directory/'analysis.json').exists():
            fault['analysisSummary']=json.loads((directory/'analysis.json').read_text())['summary']
    return {'subjects':subjects,'history':attempts,'aggregate':aggregate}


def render(data):
    payload=json.dumps(data,separators=(',',':'),allow_nan=False).replace('<','\\u003c')
    return TEMPLATE.replace('__DATA__',payload)


def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--root',type=Path,required=True);p.add_argument('--output',type=Path,required=True)
    args=p.parse_args();args.output.parent.mkdir(parents=True,exist_ok=True);args.output.write_text(render(collect(args.root)))

